function ecCloudTxt(){ return {ok:'',off:'💾 이 PC 에만 저장 (서버 클립 저장소 준비 중)',nolog:'💾 이 PC 에만 저장 — 로그인하면 서버에도 올려요',net:'💾 오프라인 — 다시 연결되면 올려요'}[ECC.st] ?? '💾 이 PC 에 저장'; } /* b356: 서버 저장(ok) 안내 문구 없앰 — 카드 ☁ 배지만 */
function ecBadge(m){ return m.up===1?'<span class="ecup on" title="서버에 저장됨">☁</span>':m.up===-1?'<span class="ecup bad" title="이 PC 에만">💾</span>':m.remote&&!m.poster?'':'<span class="ecup" title="서버에 올릴 예정">⏳</span>'; }
